import{_ as t,o,c as a,a2 as n}from"./chunks/framework.l66uSLlc.js";const u=JSON.parse('{"title":"Install and first open","description":"","frontmatter":{},"headers":[],"relativePath":"guide/install.md","filePath":"guide/install.md","lastUpdated":1792727050000}'),s={name:"guide/install.md"};function i(r,e,l,d,p,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="install-and-first-open" tabindex="-1">Install and first open <a class="header-anchor" href="#install-and-first-open" aria-label="Permalink to &quot;Install and first open&quot;">​</a></h1><p>The newest build is on the <a href="./../download">Download</a> page, and every build is on the <a href="https://github.com/roobli/Noto/releases" target="_blank" rel="noreferrer">releases page</a>. The current release is <strong>0.0.3</strong>, the first outside alpha, published on 17 October 2026. Alphas continue between releases and are labelled.</p><p>0.0.3 ships unsigned on purpose: on macOS it is ad-hoc signed and not notarized, and on Windows the installer is not code-signed. Until Noto is signed with an Apple Developer ID and notarized (and an equivalent Windows certificate), macOS and Windows warn once the first time you open a download; Linux packages are not code-signed and need no such warning. That is expected. Follow the steps below so the first launch is smooth.</p><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><p>Mac builds come as a zip; there is no <code>.dmg</code> yet.</p><ol><li><p>Download <code>Noto-&lt;version&gt;-macos-arm64.zip</code> for Apple silicon, or <code>Noto-&lt;version&gt;-macos-x64.zip</code> for an Intel Mac. The Intel zip is in releases after <code>v0.0.2-alpha.113</code>; before that, an Intel Mac has no build it can run.</p></li><li><p>Unzip. You should get <code>Noto.app</code> (move it to <code>/Applications</code> if you like).</p></li><li><p><strong>First open.</strong> Double-click <code>Noto.app</code> once. macOS says it cannot check Noto for malicious software; click <strong>Done</strong>. Then open <strong>System Settings → Privacy &amp; Security</strong>, scroll down to <strong>Security</strong>, and click <strong>Open Anyway</strong> next to the message about Noto. It is there for about an hour after you tried to open the app. Confirm in the dialog that follows and enter your login password. From then on Noto opens with a double-click.</p><p>Or in Terminal, from the folder that contains <code>Noto.app</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">xattr</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -cr</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> Noto.app</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> &amp;&amp; </span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">open</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> Noto.app</span></span></code></pre></div><p>On macOS 14 Sonoma and older you can also Right-click (or Control-click) <code>Noto.app</code>, choose <strong>Open</strong>, then confirm <strong>Open</strong>. From macOS 15 Sequoia on that shortcut is gone; use <strong>Open Anyway</strong> or the Terminal line.</p></li></ol><h3 id="what-the-dialogs-mean" tabindex="-1">What the dialogs mean <a class="header-anchor" href="#what-the-dialogs-mean" aria-label="Permalink to &quot;What the dialogs mean&quot;">​</a></h3><div class="table-scroll"><table><colgroup><col style="width:34.9%;"><col style="width:65.1%;"></colgroup><thead><tr><th>Dialog</th><th>What to do</th></tr></thead><tbody><tr><td><strong>&quot;Noto&quot; Not Opened</strong> / <strong>Apple could not verify &quot;Noto&quot; is free of malware</strong> / <strong>unidentified developer</strong></td><td>Try to open Noto once, then <strong>System Settings → Privacy &amp; Security → Open Anyway</strong> and enter your login password. Or run the <code>xattr</code> line above. On macOS 14 and older, Right-click → <strong>Open</strong> also works. After that, double-click works.</td></tr><tr><td><strong>&quot;Noto&quot; is damaged and can&#39;t be opened</strong></td><td>Re-download the zip from the current release (avoid an old cached copy). Then run <code>xattr -cr Noto.app</code> and open it again.</td></tr></tbody></table></div><p>True notarization (no Gatekeeper prompt) needs an Apple Developer identity on the release machine. Until then, the warning on first open is normal.</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><ol><li>Download <code>NotoSetup-&lt;version&gt;.exe</code>.</li><li>Run the installer. If SmartScreen says <strong>Windows protected your PC</strong>, click <strong>More info</strong>, then <strong>Run anyway</strong>.</li><li>Finish the installer and launch Noto from the Start menu.</li></ol><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><ul><li><strong>Debian / Ubuntu:</strong> <code>sudo apt install ./noto_&lt;version&gt;_amd64.deb</code> (exact filename varies by tag; check the release assets).</li><li><strong>Fedora / openSUSE:</strong> <code>sudo rpm -i noto-&lt;version&gt;-1.x86_64.rpm</code></li></ul><p>No code signing is required on typical Linux desktops for these packages.</p><h2 id="in-app-updates" tabindex="-1">In-app updates <a class="header-anchor" href="#in-app-updates" aria-label="Permalink to &quot;In-app updates&quot;">​</a></h2><p>Packaged builds can check GitHub Releases from <strong>Settings → Updates</strong>:</p><ul><li><strong>Stable</strong> (default) — formal releases only</li><li><strong>Testing</strong> — includes prerelease alphas</li></ul><p>Check-on-launch is off by default. Until builds are signed, Noto does not install an update itself on any platform: a found update opens its download on the release page, and you install it as above. That holds from the first release after 0.0.3 (<a href="https://github.com/roobli/Noto/pull/329" target="_blank" rel="noreferrer">roobli/Noto#329</a>), which also hides the setting to download automatically. An unsigned app replacing itself silently is exactly what the system&#39;s first-open warnings exist to stop.</p><h2 id="after-install" tabindex="-1">After install <a class="header-anchor" href="#after-install" aria-label="Permalink to &quot;After install&quot;">​</a></h2><p>See <a href="./using">Using Noto</a> for the day-to-day shortcuts and the vault rail.</p>',20)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
